      "mainEntity": [
        {
          "@type": "Question",
          "name": "Does a recurring blockage mean the drain must be replaced?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Not automatically. The condition and cause need assessment. Ask what the initial clearing covers and what evidence would justify further investigation or repair before approving excavation or replacement."
          }
        },
        {
          "@type": "Question",
          "name": "Is a camera inspection included in every drain-clearing job?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Do not assume it is included. Ask whether further investigation is needed, what method is proposed and whether it is a separate scope and charge. Availability of a particular inspection method should be confirmed for the job."
          }
        },
        {
          "@type": "Question",
          "name": "Why do drains keep blocking after they have been cleared?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "An unresolved restriction or other underlying drainage problem can cause recurrence. Further investigation should establish the next scope. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Is a slow-flushing toilet always caused by a blocked drain?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Poor flushing can involve the cistern or toilet fixture as well as downstream drainage. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Why does my kitchen sink gurgle and drain slowly?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A drainage restriction can cause slow flow and gurgling, but the noise cannot identify its location or cause. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to diagnose the problem first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Describe the observable change and property context. We inspect the affected area on site to establish the cause and confirm the repair scope. If more access is needed, we agree it with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "What details help with a blocked-drain request?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Tell us the affected fixture, whether water backs up elsewhere, when it began and whether the issue is getting worse."
          }
        },
        {
          "@type": "Question",
          "name": "Should I keep using a blocked fixture?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Avoid using a fixture that is overflowing or causing water to return elsewhere. Do not use chemicals as a substitute for a repair assessment."
          }
        },
        {
          "@type": "Question",
          "name": "Can a blocked toilet be related to a drain issue?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It can be useful to note whether other fixtures are slow, gurgling or backing up. Use the Toilet Repairs page for a toilet-specific concern and include all visible symptoms in the enquiry."
          }
        },
        {
          "@type": "Question",
          "name": "Can you help with property-managed drainage issues?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Include the property reference, access details and approval contact."
          }
        },
        {
          "@type": "Question",
          "name": "Does a blocked-drain quote include pipe replacement?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Clearing and pipe replacement are different scopes. We identify the proposed treatment and any separate investigation or repair in the written quote before additional work proceeds."
          }
        }
      ]
    }
  ]
}

